    @classmethod
    def InitFromPackedBuf(cls, buf, pos=0):
        n = flatbuffers.encode.Get(flatbuffers.packer.uoffset, buf, pos)
        return cls.InitFromBuf(buf, pos+n)

    @classmethod
    def InitFromObj(cls, tmpDcl):
        x = DCLT()
        x._UnPack(tmpDcl)
        return x

    # DCLT
    def _UnPack(self, DCL):
        if DCL is None:
            return
        self.ID = DCL.ID()
        self.CREATED_AT_MS = DCL.CREATED_AT_MS()
        self.PRODUCER = DCL.PRODUCER()
        self.PRODUCT = DCL.PRODUCT()
        if DCL.ATMOSPHERE() is not None:
            self.ATMOSPHERE = ATM.ATMT.InitFromObj(DCL.ATMOSPHERE())
        if DCL.JB2008_DRIVERS() is not None:
            self.JB2008_DRIVERS = PRWJB2008IndicesTable.PRWJB2008IndicesTableT.InitFromObj(DCL.JB2008_DRIVERS())
        if not DCL.SPACE_WEATHERIsNone():
            self.SPACE_WEATHER = []
            for i in range(DCL.SPACE_WEATHERLength()):
                if DCL.SPACE_WEATHER(i) is None:
                    self.SPACE_WEATHER.append(None)
                else:
                    sPW_ = SPW.SPWT.InitFromObj(DCL.SPACE_WEATHER(i))
                    self.SPACE_WEATHER.append(sPW_)
        self.GRAVITY_FIELD = DCL.GRAVITY_FIELD()
        self.GRAVITY_DEGREE = DCL.GRAVITY_DEGREE()
        self.GRAVITY_ORDER = DCL.GRAVITY_ORDER()
        self.GM_M3_S2 = DCL.GM_M3_S2()
        self.EARTH_ROTATION_RAD_S = DCL.EARTH_ROTATION_RAD_S()
        self.BALLISTIC_COEFFICIENT_M2_KG = DCL.BALLISTIC_COEFFICIENT_M2_KG()
        if DCL.SETTINGS() is not None:
            self.SETTINGS = dclSettings.dclSettingsT.InitFromObj(DCL.SETTINGS())
        if DCL.CORRECTION() is not None:
            self.CORRECTION = dclCorrection.dclCorrectionT.InitFromObj(DCL.CORRECTION())
        self.STATUS = DCL.STATUS()
        self.ERROR_CODE = DCL.ERROR_CODE()
        self.ERROR_MESSAGE = DCL.ERROR_MESSAGE()
        if DCL.POINTS() is not None:
            self.POINTS = dclPoints.dclPointsT.InitFromObj(DCL.POINTS())
        if not DCL.OBJECTSIsNone():
            self.OBJECTS = []
            for i in range(DCL.OBJECTSLength()):
                if DCL.OBJECTS(i) is None:
                    self.OBJECTS.append(None)
                else:
                    dclObject_ = dclObject.dclObjectT.InitFromObj(DCL.OBJECTS(i))
                    self.OBJECTS.append(dclObject_)
        if DCL.FIT() is not None:
            self.FIT = dclFitStatistics.dclFitStatisticsT.InitFromObj(DCL.FIT())
        if not DCL.LEVELSIsNone():
            self.LEVELS = []
            for i in range(DCL.LEVELSLength()):
                if DCL.LEVELS(i) is None:
                    self.LEVELS.append(None)
                else:
                    dclLevel_ = dclLevel.dclLevelT.InitFromObj(DCL.LEVELS(i))
                    self.LEVELS.append(dclLevel_)
        if not DCL.HISTORYIsNone():
            self.HISTORY = []
            for i in range(DCL.HISTORYLength()):
                if DCL.HISTORY(i) is None:
                    self.HISTORY.append(None)
                else:
                    dclIteration_ = dclIteration.dclIterationT.InitFromObj(DCL.HISTORY(i))
                    self.HISTORY.append(dclIteration_)
        self.LEVEL_LN_B_CORRELATION = DCL.LEVEL_LN_B_CORRELATION()
        self.MEAN_LEVEL_SIGMA_K = DCL.MEAN_LEVEL_SIGMA_K()
        if DCL.STATES() is not None:
            self.STATES = dclStates.dclStatesT.InitFromObj(DCL.STATES())

    # DCLT
    def Pack(self, builder):
        if self.ID is not None:
            ID = builder.CreateString(self.ID)
        if self.PRODUCER is not None:
            PRODUCER = builder.CreateString(self.PRODUCER)
        if self.ATMOSPHERE is not None:
            ATMOSPHERE = self.ATMOSPHERE.Pack(builder)
        if self.JB2008_DRIVERS is not None:
            JB2008_DRIVERS = self.JB2008_DRIVERS.Pack(builder)
        if self.SPACE_WEATHER is not None:
            SPACE_WEATHERlist = []
            for i in range(len(self.SPACE_WEATHER)):
                SPACE_WEATHERlist.append(self.SPACE_WEATHER[i].Pack(builder))
            DCLStartSPACE_WEATHERVector(builder, len(self.SPACE_WEATHER))
            for i in reversed(range(len(self.SPACE_WEATHER))):
                builder.PrependUOffsetTRelative(SPACE_WEATHERlist[i])
            SPACE_WEATHER = builder.EndVector()
        if self.GRAVITY_FIELD is not None:
            GRAVITY_FIELD = builder.CreateString(self.GRAVITY_FIELD)
        if self.SETTINGS is not None:
            SETTINGS = self.SETTINGS.Pack(builder)
        if self.CORRECTION is not None:
            CORRECTION = self.CORRECTION.Pack(builder)
        if self.ERROR_CODE is not None:
            ERROR_CODE = builder.CreateString(self.ERROR_CODE)
        if self.ERROR_MESSAGE is not None:
            ERROR_MESSAGE = builder.CreateString(self.ERROR_MESSAGE)
        if self.POINTS is not None:
            POINTS = self.POINTS.Pack(builder)
        if self.OBJECTS is not None:
            OBJECTSlist = []
            for i in range(len(self.OBJECTS)):
                OBJECTSlist.append(self.OBJECTS[i].Pack(builder))
            DCLStartOBJECTSVector(builder, len(self.OBJECTS))
            for i in reversed(range(len(self.OBJECTS))):
                builder.PrependUOffsetTRelative(OBJECTSlist[i])
            OBJECTS = builder.EndVector()
        if self.FIT is not None:
            FIT = self.FIT.Pack(builder)
        if self.LEVELS is not None:
            LEVELSlist = []
            for i in range(len(self.LEVELS)):
                LEVELSlist.append(self.LEVELS[i].Pack(builder))
            DCLStartLEVELSVector(builder, len(self.LEVELS))
            for i in reversed(range(len(self.LEVELS))):
                builder.PrependUOffsetTRelative(LEVELSlist[i])
            LEVELS = builder.EndVector()
        if self.HISTORY is not None:
            HISTORYlist = []
            for i in range(len(self.HISTORY)):
                HISTORYlist.append(self.HISTORY[i].Pack(builder))
            DCLStartHISTORYVector(builder, len(self.HISTORY))
            for i in reversed(range(len(self.HISTORY))):
                builder.PrependUOffsetTRelative(HISTORYlist[i])
            HISTORY = builder.EndVector()
        if self.STATES is not None:
            STATES = self.STATES.Pack(builder)
        DCLStart(builder)
        if self.ID is not None:
            DCLAddID(builder, ID)
        DCLAddCREATED_AT_MS(builder, self.CREATED_AT_MS)
        if self.PRODUCER is not None:
            DCLAddPRODUCER(builder, PRODUCER)
        DCLAddPRODUCT(builder, self.PRODUCT)
        if self.ATMOSPHERE is not None:
            DCLAddATMOSPHERE(builder, ATMOSPHERE)
        if self.JB2008_DRIVERS is not None:
            DCLAddJB2008_DRIVERS(builder, JB2008_DRIVERS)
        if self.SPACE_WEATHER is not None:
            DCLAddSPACE_WEATHER(builder, SPACE_WEATHER)
        if self.GRAVITY_FIELD is not None:
            DCLAddGRAVITY_FIELD(builder, GRAVITY_FIELD)
        DCLAddGRAVITY_DEGREE(builder, self.GRAVITY_DEGREE)
        DCLAddGRAVITY_ORDER(builder, self.GRAVITY_ORDER)
        DCLAddGM_M3_S2(builder, self.GM_M3_S2)
        DCLAddEARTH_ROTATION_RAD_S(builder, self.EARTH_ROTATION_RAD_S)
        DCLAddBALLISTIC_COEFFICIENT_M2_KG(builder, self.BALLISTIC_COEFFICIENT_M2_KG)
        if self.SETTINGS is not None:
            DCLAddSETTINGS(builder, SETTINGS)
        if self.CORRECTION is not None:
            DCLAddCORRECTION(builder, CORRECTION)
        DCLAddSTATUS(builder, self.STATUS)
        if self.ERROR_CODE is not None:
            DCLAddERROR_CODE(builder, ERROR_CODE)
        if self.ERROR_MESSAGE is not None:
            DCLAddERROR_MESSAGE(builder, ERROR_MESSAGE)
        if self.POINTS is not None:
            DCLAddPOINTS(builder, POINTS)
        if self.OBJECTS is not None:
            DCLAddOBJECTS(builder, OBJECTS)
        if self.FIT is not None:
            DCLAddFIT(builder, FIT)
        if self.LEVELS is not None:
            DCLAddLEVELS(builder, LEVELS)
        if self.HISTORY is not None:
            DCLAddHISTORY(builder, HISTORY)
        DCLAddLEVEL_LN_B_CORRELATION(builder, self.LEVEL_LN_B_CORRELATION)
        DCLAddMEAN_LEVEL_SIGMA_K(builder, self.MEAN_LEVEL_SIGMA_K)
        if self.STATES is not None:
            DCLAddSTATES(builder, STATES)
        DCL = DCLEnd(builder)
        return DCL
